import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
    static <T> List<T> takrorlar(List<T> a) {
        List<T> natija = new ArrayList<>();
        for (T x : a) {
            if (natija.isEmpty() || !natija.get(natija.size() - 1).equals(x)) natija.add(x);
        }
        return natija;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        List<Integer> sonlar = new ArrayList<>();
        for (String s : in.nextLine().trim().split("\\s+")) sonlar.add(Integer.parseInt(s));
        List<String> sozlar = Arrays.asList(in.nextLine().trim().split("\\s+"));

        StringBuilder sb = new StringBuilder();
        for (int x : takrorlar(sonlar)) {
            if (sb.length() > 0) sb.append(' ');
            sb.append(x);
        }
        System.out.println(sb);

        StringBuilder sb2 = new StringBuilder();
        for (String s : takrorlar(sozlar)) {
            if (sb2.length() > 0) sb2.append(' ');
            sb2.append(s);
        }
        System.out.println(sb2);
    }
}

